"use client";

import { useEffect, useState } from "react";
import Link from "next/link";
import { useParams } from "next/navigation";
import AppShell from "@/components/Navbar";
import { api } from "@/lib/api";

interface FacultyLoadDetail {
  instructor_id: number;
  full_name: string;
  dept_name: string | null;
  max_units: number;
  max_classes: number;
  current_units: number;
  current_classes: number;
  remaining_units: number;
  remaining_classes: number;
}

interface ShowResponse {
  success: boolean;
  message: string;
  data: FacultyLoadDetail;
}

export default function AdminFacultyLoadDetailPage() {
  const params = useParams<{ id: string }>();
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [success, setSuccess] = useState<string | null>(null);
  const [detail, setDetail] = useState<FacultyLoadDetail | null>(null);
  const [maxUnits, setMaxUnits] = useState("");
  const [maxClasses, setMaxClasses] = useState("");

  useEffect(() => {
    (async () => {
      try {
        setLoading(true);
        setError(null);
        const res = await api.get<ShowResponse>(`/admin/faculty-load/${params.id}`);
        setDetail(res.data);
        setMaxUnits(String(res.data.max_units));
        setMaxClasses(String(res.data.max_classes));
      } catch (e) {
        setError(e instanceof Error ? e.message : "Failed to load faculty detail.");
      } finally {
        setLoading(false);
      }
    })();
  }, [params.id]);

  async function onSave(e: React.FormEvent) {
    e.preventDefault();
    if (!detail) return;
    try {
      setSaving(true);
      setError(null);
      setSuccess(null);
      await api.patch(`/admin/faculty-load/${params.id}`, {
        instructor_id: detail.instructor_id,
        max_units: Number(maxUnits),
        max_classes: Number(maxClasses),
      });
      setSuccess("Faculty load limit updated successfully.");
    } catch (e) {
      setError(e instanceof Error ? e.message : "Failed to save changes.");
    } finally {
      setSaving(false);
    }
  }

  const unitsPct = detail ? Math.min((detail.current_units / (Number(maxUnits) || 1)) * 100, 100) : 0;
  const classesPct = detail ? Math.min((detail.current_classes / (Number(maxClasses) || 1)) * 100, 100) : 0;

  return (
    <AppShell role="admin" userName="Admin" pageTitle="Faculty Load Detail">
      <div className="space-y-6">
        <nav className="flex items-center gap-2 text-xs" style={{ color: "var(--color-text-muted)" }}>
          <Link href="/admin/faculty-load" style={{ color: "var(--color-primary-light)" }}>Faculty Load</Link>
          <span>/</span>
          <span>{detail?.full_name ?? "Detail"}</span>
        </nav>

        {error && <div className="rounded-lg border px-3 py-2 text-[12px]" style={{ borderColor: "#fecaca", background: "#fff1f2", color: "#9f1239" }}>{error}</div>}
        {success && <div className="rounded-lg border px-3 py-2 text-[12px]" style={{ borderColor: "#bbf7d0", background: "#f0fdf4", color: "#166534" }}>{success}</div>}

        {loading || !detail ? (
          <div className="card card-body">Loading...</div>
        ) : (
          <>
            <div className="card card-body">
              <h1 className="text-lg font-semibold">{detail.full_name}</h1>
              <p className="text-sm" style={{ color: "var(--color-text-secondary)" }}>Instructor ID: {detail.instructor_id} · {detail.dept_name ?? "N/A"}</p>
            </div>

            <div className="grid grid-cols-2 sm:grid-cols-4 gap-4">
              <MiniStat label="Current Units" value={detail.current_units.toFixed(1)} note={`${detail.remaining_units.toFixed(1)} remaining`} />
              <MiniStat label="Current Classes" value={String(detail.current_classes)} note={`${detail.remaining_classes} remaining`} />
              <MiniStat label="Max Units" value={maxUnits} note="editable" />
              <MiniStat label="Max Classes" value={maxClasses} note="editable" />
            </div>

            <div className="card card-body space-y-4">
              <h2 className="text-sm font-semibold">Load Utilization Preview</h2>
              <div>
                <div className="flex justify-between text-xs"><span>Units</span><span>{detail.current_units.toFixed(1)} / {Number(maxUnits || 0).toFixed(1)}</span></div>
                <div className="h-2 rounded-full mt-1" style={{ background: "var(--color-surface-2)" }}>
                  <div className="h-2 rounded-full" style={{ width: `${unitsPct}%`, background: unitsPct >= 100 ? "var(--color-error)" : "var(--color-primary-light)" }} />
                </div>
              </div>
              <div>
                <div className="flex justify-between text-xs"><span>Classes</span><span>{detail.current_classes} / {maxClasses || 0}</span></div>
                <div className="h-2 rounded-full mt-1" style={{ background: "var(--color-surface-2)" }}>
                  <div className="h-2 rounded-full" style={{ width: `${classesPct}%`, background: classesPct >= 100 ? "var(--color-error)" : "var(--color-info)" }} />
                </div>
              </div>
            </div>

            <form className="card card-body space-y-4" onSubmit={onSave}>
              <h2 className="text-sm font-semibold">Edit Load Limits</h2>
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                <div className="form-group">
                  <label className="form-label">Maximum Teaching Units</label>
                  <input type="number" min={0} step={0.5} value={maxUnits} onChange={(e) => setMaxUnits(e.target.value)} />
                </div>
                <div className="form-group">
                  <label className="form-label">Maximum Class Sections</label>
                  <input type="number" min={0} value={maxClasses} onChange={(e) => setMaxClasses(e.target.value)} />
                </div>
              </div>
              <div className="flex gap-3">
                <button className="btn btn-primary" disabled={saving}>{saving ? "Saving..." : "Save Changes"}</button>
                <button type="button" className="btn btn-ghost" onClick={() => {
                  setMaxUnits(String(detail.max_units));
                  setMaxClasses(String(detail.max_classes));
                }}>Discard</button>
              </div>
            </form>
          </>
        )}
      </div>
    </AppShell>
  );
}

function MiniStat({ label, value, note }: { label: string; value: string; note: string }) {
  return (
    <div className="card card-body">
      <p className="text-xs mb-1" style={{ color: "var(--color-text-secondary)" }}>{label}</p>
      <p className="text-2xl font-bold leading-none">{value}</p>
      <p className="text-xs mt-1" style={{ color: "var(--color-text-muted)" }}>{note}</p>
    </div>
  );
}
